import sys, json, random, subprocess, hashlib
sys.path.insert(0,'/app/tmp/t')
from harness import *

random.seed(1234)
C = cfg()
GOOD = basic_req()

# 1) fuzz random wire bytes -> must always exit 0 with well-formed results
reasons = set()
for trial in range(300):
    n = random.randint(0, 400)
    style = random.randint(0,3)
    if style == 0:
        data = bytes(random.getrandbits(8) for _ in range(n))
    elif style == 1:
        data = bytearray(GOOD)
        for _ in range(random.randint(1,8)):
            if data: data[random.randrange(len(data))] = random.getrandbits(8)
        data = bytes(data)
    elif style == 2:
        # random header soup
        lines = []
        for _ in range(random.randint(0,6)):
            name = "".join(random.choice("Abc-.!%*_+`'~") for _ in range(random.randint(1,8)))
            val = "".join(chr(random.randint(32,126)) for _ in range(random.randint(0,20)))
            lines.append(name + ": " + val)
        body = bytes(random.getrandbits(8) for _ in range(random.randint(0,10)))
        data = ("\r\n".join(["MESSAGE sip:bob@lab.test SIP/2.0"] + lines) + "\r\n\r\n").encode() + body
    else:
        data = GOOD if random.random()<0.5 else GOOD.replace(b"alice", b"bob")
    evs = [ev(trial, random.choice(["edge","relay"]), random.choice([None,"alice","bob"]),
              random.choice(["internal","external"]), data)]
    p = run(env(C, evs))
    if p.returncode != 0:
        FAILS.append(("fuzz wire", p.returncode, p.stderr.decode()[:600]))
        print("CRASH", p.stderr.decode()[:800]); break
    out = json.loads(p.stdout)
    for r in out["results"]:
        if r["decision"] == "reject":
            reasons.add(r["reason"])
            if set(r) != {"index","decision","reason"}: FAILS.append(("fuzz keys", r))
        else:
            need = {"index","decision","first","account","identity","from","pai","method",
                    "target","call_id","cseq","tag","privacy","body_sha256"}
            if set(r) != need: FAILS.append(("fuzz keys2", r)); print(set(r)^need)
print("fuzz wire reasons seen:", sorted(reasons))

# 2) fuzz envelope structure -> must be 0 or 2, never crash with traceback
import copy
for trial in range(400):
    d = copy.deepcopy(env(C, [ev(0,"edge","alice","internal",GOOD), ev(1,"edge","alice","external",GOOD)]))
    def rndkey(o, depth=0):
        if isinstance(o, dict):
            ks = list(o) + [None]
            return random.choice(ks)
        if isinstance(o, list) and o:
            return random.randrange(len(o)+1) - 1
        return None
    for _ in range(random.randint(1,4)):
        try:
            pick = random.randint(0,7)
            if pick == 0:
                k = random.choice(list(d)); d[k] = random.choice([None,"x",[],{},-1,1.5,True])
            elif pick == 1:
                k = random.choice(list(d["config"])); d["config"][k] = random.choice([None,"x",[],{},-1,1.5,True])
            elif pick == 2 and d["config"]["accounts"]:
                a = random.choice(d["config"]["accounts"]); k=random.choice(list(a)); a[k]=random.choice([None,"x",[],{},1.5])
            elif pick == 3 and d["config"]["peers"]:
                a = random.choice(d["config"]["peers"]); k=random.choice(list(a)); a[k]=random.choice([None,"x",[],{},1.5])
            elif pick == 4 and d["events"]:
                e = random.choice(d["events"]); k=random.choice(list(e)); e[k]=random.choice([None,"x",[],{},1.5,True,-1])
            elif pick == 5:
                d["events"].pop() if d["events"] and random.random()<0.5 else d["events"].append(copy.deepcopy(random.choice(d["events"])) if d["events"] else 1)
            elif pick == 6:
                d["config"]["peers"].append(copy.deepcopy(random.choice(d["config"]["peers"])))
            else:
                d["config"]["accounts"].append({"id":"zz","default":"sip:zz@x.test","aliases":["sip:zz@x.test"]})
        except Exception: pass
    p = run(d)
    if p.returncode not in (0,2) or (p.returncode==2 and p.stdout) or (p.returncode==0 and not p.stdout):
        FAILS.append(("fuzz env", p.returncode, p.stdout[:100], p.stderr.decode()[:400]))
        print("CRASH ENV", p.returncode, p.stderr.decode()[:600]); break
    if p.returncode == 0:
        json.loads(p.stdout)

sys.exit(summary())
